+// API keys and roles. `viewer` reads (GET); `cook` also does the kitchen's
+// daily writes; `manager` may do everything.
+import { AppError } from "../errors.js";
+import { router } from "./router.js";
+
+const RANK = { viewer: 1, cook: 2, manager: 3 };
+
+const noop = () => null;
+const cookRoutes = router([
+  ["POST", "/recipes/:id/cook", noop],
+  ["POST", "/batches/:id/waste", noop],
+  ["POST", "/temperatures", noop],
+  ["POST", "/stocktakes/:id/counts", noop],
+]);
+
+/** The key record sent in the Authorization header; throws unauthorized if missing or unknown. */
+export function authenticate(store, headers) {
+  const name = Object.keys(headers).find((h) => h.toLowerCase() === "authorization");
+  const m = /^Bearer\s+(\S+)$/.exec(name ? String(headers[name]).trim() : "");
+  const found = m && store.data.apiKeys.find((k) => k.key === m[1]);
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** The lowest role allowed to make this request. */
+export function requiredRole(method, path) {
+  if (path === "/audit") return "manager";
+  if (method === "GET") return "viewer";
+  return cookRoutes(method, path) ? "cook" : "manager";
+}
+
+/** Throws forbidden unless the key's role may make this request. */
+export function authorize(apiKey, method, path) {
+  const need = requiredRole(method, path);
+  if ((RANK[apiKey.role] ?? 0) < RANK[need]) throw new AppError("forbidden", { role: need });
+}
