+++ b/tests/auth.test.js
@@ -0,0 +1,36 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, KEYS } from "./helpers.js";
+
+const as = (role) => ({ authorization: `Bearer ${KEYS[role]}` });
+
+test("missing or unknown keys are 401", async () => {
+  const { raw } = app();
+  const a = await raw({ path: "/items" });
+  assert.equal(a.status, 401);
+  assert.equal(a.body.error.code, "unauthorized");
+  assert.equal((await raw({ path: "/items", headers: { authorization: "Bearer nope" } })).status, 401);
+});
+
+test("roles limit what a key may do", async () => {
+  const { raw } = app();
+  assert.equal((await raw({ path: "/items", headers: as("viewer") })).status, 200);
+  const denied = await raw({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 }, headers: as("viewer") });
+  assert.equal(denied.status, 403);
+  assert.equal(denied.body.error.code, "forbidden");
+  assert.equal((await raw({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 }, headers: as("cook") })).status, 200);
+  assert.equal((await raw({ method: "POST", path: "/orders", body: {}, headers: as("cook") })).status, 403);
+  assert.equal((await raw({ path: "/audit", headers: as("cook") })).status, 403);
+});
+
+test("changes are audited, newest first", async () => {
+  const { raw } = app();
+  await raw({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 }, headers: as("cook") });
+  await raw({ method: "POST", path: "/orders", body: {}, headers: as("cook") });
+  await raw({ path: "/items", headers: as("cook") });
+  const log = (await raw({ path: "/audit", headers: as("manager") })).body;
+  assert.deepEqual(log.map((e) => [e.key, e.method, e.path, e.status]), [
+    ["dev-cook", "POST", "/orders", 403],
+    ["dev-cook", "POST", "/recipes/1/cook", 200],
+  ]);
+});
